        all_ids.remove(depot)
    if not all_ids:
        return []

    for cid in list(all_ids):
        if cid not in demand:
            demand[cid] = 0

    def coord_of(cid):
        c = coords.get(cid, None)
        if c is None or len(c) < 2:
            return None
        return c[0], c[1]

    def dist(a, b):
        ca = coord_of(a)
        cb = coord_of(b)
        if ca is None or cb is None:
            return 0.0 if a == b else 1.0
        dx = ca[0] - cb[0]
        dy = ca[1] - cb[1]
        return (dx * dx + dy * dy) ** 0.5

    customers_list = list(all_ids)
    if coord_of(depot) is not None and all(coord_of(c) is not None for c in customers_list):
        dx0, dy0 = coord_of(depot)

        def angle_key(cid):
            x, y = coord_of(cid)
            x -= dx0
            y -= dy0
            if x >= 0 and y >= 0:
                quad = 0
            elif x < 0 <= y:
                quad = 1
            elif x < 0 and y < 0:
                quad = 2
            else:
                quad = 3
            slope = y / x if x != 0 else (10**18 if y >= 0 else -10**18)
            return (quad, slope, dist(depot, cid), cid)

        customers_list.sort(key=angle_key)
    else:
        customers_list.sort()

    def route_load(route):
        s = 0
        for c in route:
            s += demand.get(c, 0)
        return s

    def route_cost(route):
        if not route:
            return 0.0
        cost = dist(depot, route[0])
        for i in range(len(route) - 1):
            cost += dist(route[i], route[i + 1])
        cost += dist(route[-1], depot)
        return cost

    # Constructive phase: sweep + nearest feasible continuation
    routes = []
    unserved = customers_list[:]
    while unserved:
        feasible = [cid for cid in unserved if demand.get(cid, 0) <= capacity]
        if not feasible:
            routes.append([unserved.pop(0)])
            continue

        seed = min(feasible, key=lambda c: (dist(depot, c), -demand.get(c, 0), c))
        route = [seed]
        load = demand.get(seed, 0)
        unserved.remove(seed)
        current = seed

        while True:
            candidates = [cid for cid in unserved if load + demand.get(cid, 0) <= capacity]
            if not candidates:
                break
            best = None
            best_key = None
            for cid in candidates:
                d = dist(current, cid)
                extra_to_end = d + dist(cid, depot) - dist(current, depot)
                slack = capacity - (load + demand.get(cid, 0))
                key = (extra_to_end, d, slack, -demand.get(cid, 0), cid)
                if best_key is None or key < best_key:
                    best_key = key
                    best = cid
            route.append(best)
            load += demand.get(best, 0)
            unserved.remove(best)
            current = best

        routes.append(route)

    # Repair: if any route exceeds capacity, split greedily
    repaired = []
    for route in routes:
        cur = []
        load = 0
        for cid in route:
            d = demand.get(cid, 0)
            if cur and load + d > capacity:
                repaired.append(cur)
                cur = [cid]
                load = d
            else:
                cur.append(cid)
                load += d
        if cur:
            repaired.append(cur)
    routes = repaired

    # Local search: relocate and swap between routes, deterministic best-improvement
    def total_cost(rs):
        s = 0.0
        for r in rs:
            s += route_cost(r)
        return s

    improved = True
    while improved:
        improved = False
        best_delta = 0.0
        best_move = None
        base = total_cost(routes)

        # relocate
        for i in range(len(routes)):
            for pi, cid in enumerate(routes[i]):
                dem = demand.get(cid, 0)
                for j in range(len(routes)):
                    if i == j and len(routes[i]) == 1:
                        continue
                    for pos in range(len(routes[j]) + 1):
                        if i == j and (pos == pi or pos == pi + 1):
                            continue
                        ni = routes[i][:pi] + routes[i][pi + 1:]
                        nj = routes[j][:pos] + [cid] + routes[j][pos:]
                        if not ni or route_load(nj) > capacity or (i == j and route_load(ni) > capacity):
                            continue
                        cand = routes[:]
                        cand[i] = ni
                        cand[j] = nj
                        delta = total_cost(cand) - base
                        if delta < best_delta - 1e-12 or (delta == best_delta and best_move is not None and (i, j, pi, pos, cid) < best_move[0]):
                            best_delta = delta
                            best_move = ((i, j, pi, pos, cid), cand)

        if best_move is not None:
            routes = best_move[1]
            improved = True
            continue

        # swap
        base = total_cost(routes)
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                for pi, ci in enumerate(routes[i]):
                    di = demand.get(ci, 0)
                    for pj, cj in enumerate(routes[j]):
                        dj = demand.get(cj, 0)
                        li = route_load(routes[i]) - di + dj
                        lj = route_load(routes[j]) - dj + di
                        if li > capacity or lj > capacity:
                            continue
                        ni = routes[i][:]
                        nj = routes[j][:]
                        ni[pi] = cj
                        nj[pj] = ci
                        cand = routes[:]
                        cand[i] = ni
                        cand[j] = nj
                        delta = total_cost(cand) - base
                        if delta < best_delta - 1e-12 or (delta == best_delta and best_move is not None and (i, j, pi, pj, ci, cj) < best_move[0]):
                            best_delta = delta
                            best_move = ((i, j, pi, pj, ci, cj), cand)

        if best_move is not None:
            routes = best_move[1]
            improved = True

    # Final cleanup: remove empty routes and normalize deterministic order by first customer
    routes = [r for r in routes if r]
    routes.sort(key=lambda r: (r[0], len(r), r))
    return routes
